import {restoreCraps} from './craps.mjs';
export function applyWager(g,a){if(a.action==='bet')g.add(a.key,a.amount);else if(a.action==='remove')g.remove(a.key);else if(a.action==='removeTravel')g.removeTravel(a.key);else if(a.action==='clear')g.clear();else throw Error('未知下注操作')}
export function replayWagers(table,actions){const g=restoreCraps(JSON.parse(JSON.stringify(table)));for(const a of actions)applyWager(g,a);return g}
// Keep the hit targets stable while updating their values and disabled states.
export function patchBoard(node,markup){const oldButtons=[...node.querySelectorAll('[data-bet]')];if(!oldButtons.length){node.innerHTML=markup;return}const template=document.createElement('template');template.innerHTML=markup;const next=template.content;const newButtons=[...next.querySelectorAll('[data-bet]')];if(!oldButtons.length||oldButtons.length!==newButtons.length||oldButtons.some((b,i)=>b.dataset.bet!==newButtons[i].dataset.bet)){node.innerHTML=markup;return}const patch=(a,b)=>{for(const at of [...a.attributes])if(!b.hasAttribute(at.name))a.removeAttribute(at.name);for(const at of b.attributes)if(a.getAttribute(at.name)!==at.value)a.setAttribute(at.name,at.value);if(a.innerHTML!==b.innerHTML)a.innerHTML=b.innerHTML};oldButtons.forEach((b,i)=>patch(b,newButtons[i]));node.querySelectorAll('[data-bet-group]').forEach((b,i)=>patch(b,next.querySelectorAll('[data-bet-group]')[i]))}
